```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using namespace std;

int main() {
    string word;
    cout << "Введите слово для поиска: ";
    cin >> word;

    string line;
    int count = 0;
    ifstream file("filename.txt");

    if (file.is_open()) {
        while (getline(file, line)) {
            vector<string> words;
            size_t pos = 0;
            string token;
            while ((pos = line.find(" ")) != string::npos) {
                token = line.substr(pos, pos + 1);
                words.push_back(token);
                line.erase(pos, pos + 1);
            }
            words.push_back(line);

            for (auto& w : words) {
                if (w == word) {
                    count++;
                }
            }
        }
        file.close();
    } else {
        cout << "Не удалось открыть файл!" << endl;
        return 1;
    }

    cout << "Слово '" << word << "' встречается " << count << " раз(а) в файле." << endl;

    return 0;
}
```

Замените `filename.txt` на имя вашего реального файла, а затем запустите программу. После того, как вы введете слово для поиска, программа считывает каждую строку из файла, разбирает ее на слова, и подсчитывает количество вхождений введенного слова в файле.

